		"  exit 1",
		"}",
		"",
		"$popup.Show()",
		"",
		"$arguments = if ($profile -eq '') { @('web', '--no-open') } else { @('--profile', $profile, '--no-open') }",
		"if ($command.CommandType -eq 'ExternalScript' -or $command.Source -match '\\.ps1$') {",
